-- ts-design-studio 0.2.0 – konverzace s AI a spotřeba modelu (MySQL)
CREATE TABLE IF NOT EXISTS studio_messages (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, num INT NOT NULL DEFAULT 0, uid INT NOT NULL DEFAULT 0, role VARCHAR(10) NOT NULL, text TEXT NOT NULL, created_at VARCHAR(19) NOT NULL, INDEX studio_messages_project (project_id, id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS studio_usage (id INT AUTO_INCREMENT PRIMARY KEY, day VARCHAR(10) NOT NULL, project_id INT NOT NULL DEFAULT 0, uid INT NOT NULL DEFAULT 0, kind VARCHAR(10) NOT NULL, model VARCHAR(80) NOT NULL, tokens_in INT NOT NULL DEFAULT 0, tokens_out INT NOT NULL DEFAULT 0, neurons INT NOT NULL DEFAULT 0, ok TINYINT NOT NULL DEFAULT 1, created_at VARCHAR(19) NOT NULL, INDEX studio_usage_day (day)) DEFAULT CHARSET=utf8mb4;
